package com.slss.api;
import com.slss.domain.ScanTable; import com.slss.repository.ScanTableRepository; import com.slss.service.TenantScopeService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/quality/production-import") @PreAuthorize("hasAnyAuthority('PERM_VIEW_PRODUCTION','PERM_MANAGE_PRODUCTION','PERM_MANAGE_SCAN_TEMPLATE','PERM_MANAGE_SYSTEM')")
public class QualityProductionImportController { private final ScanTableRepository tables; private final TenantScopeService scope; public QualityProductionImportController(ScanTableRepository t,TenantScopeService s){tables=t;scope=s;} @GetMapping public List<Map<String,Object>> list(){return tables.findAllByOrderByCreatedAtDesc().stream().filter(t->scope.canAccess(t.getTenant())).map(this::dto).toList();} private Map<String,Object> dto(ScanTable t){var m=new LinkedHashMap<String,Object>();m.put("id",t.getId());m.put("customerName",t.getCustomerName());m.put("machineModel",t.getModel());m.put("quantity",t.getQuantity());m.put("createdAt",t.getCreatedAt());return m;}}
